/* ---- arithmetic, as sec.2.2/2.3 define it: on exact 64-bit values, with
 * floor division by powers of two written out (C's >> on a negative value
 * is implementation-defined; the spec defines the mathematics). */
static int64_t floor_shift(int64_t v,unsigned s){
    if(!s)return v;
    if(v>=0)return v>>s;
    return -((-v+(((int64_t)1<<s)-1))>>s);  /* |v| <= 2^62: -v cannot overflow */
}
static int32_t sat32(int64_t v){
    return v>INT32_MAX?INT32_MAX:v<INT32_MIN?INT32_MIN:(int32_t)v;
}
static int32_t sat16(int64_t v){
    return v>32767?32767:v<-32768?-32768:(int32_t)v;
}

bool ksn_shiki_from_double(double v,unsigned f,int32_t *out){
    if(!isfinite(v))return false;
    /* sec.2.4, in double as written: scale (exact, a power of two), clamp,
     * then round half away from zero. */
    double x=ldexp(v,(int)f);
    if(x<-2147483648.0)x=-2147483648.0;
    if(x>2147483647.0)x=2147483647.0;
    const double r=x<0?-floor(-x+0.5):floor(x+0.5);
    *out=(int32_t)r;
    return true;
}

/* ---- registration (sec.3, sec.6.1) */
enum { F_DST=1, F_A=2, F_B=4, F_IMM=8, F_AUX=16 };
/* Which fields an op uses (sec.4.3); every other field must be 0. dst/a/b
 * are registers unless noted in check_inst(). */
static const uint8_t used[KSN_SHIKI_OPS]={
    [KSN_SHIKI_SET]=F_DST|F_IMM,             [KSN_SHIKI_INPUT]=F_DST|F_A,
    [KSN_SHIKI_ADD]=F_DST|F_A|F_B,           [KSN_SHIKI_MUL]=F_DST|F_A|F_B|F_AUX,
    [KSN_SHIKI_SIN]=F_DST|F_A,               [KSN_SHIKI_REPEAT]=F_IMM,
    [KSN_SHIKI_END]=0,                       [KSN_SHIKI_MOVE]=F_A|F_B,
    [KSN_SHIKI_PLOT]=F_A|F_B|F_AUX,          [KSN_SHIKI_LINE]=F_A|F_B|F_AUX,
    [KSN_SHIKI_REPEAT_REG]=F_A,              [KSN_SHIKI_BREAK_IF_GT]=F_A|F_B,
    [KSN_SHIKI_PLOT_C]=F_DST|F_A|F_B,        [KSN_SHIKI_LINE_C]=F_DST|F_A|F_B,
    [KSN_SHIKI_SUB]=F_DST|F_A|F_B,           [KSN_SHIKI_NEG]=F_DST|F_A,
    [KSN_SHIKI_SHIFT]=F_DST|F_A|F_IMM,       [KSN_SHIKI_ADD_H]=F_DST|F_A|F_B,
    [KSN_SHIKI_SUB_H]=F_DST|F_A|F_B,         [KSN_SHIKI_MUL_H]=F_DST|F_A|F_B|F_AUX,
    [KSN_SHIKI_SHIFT_H]=F_DST|F_A|F_IMM,
};
/* Stage 1 refuses these (header comment). */
static bool stage1(uint8_t op){
    return op<KSN_SHIKI_OPS&&op!=KSN_SHIKI_CUBIC&&op!=KSN_SHIKI_LINE_PATTERN&&op<KSN_SHIKI_EACH;
}
/* imm fields that take an int (sec.3): a patched argument must be Q0. */
static bool int_imm(uint8_t op){
    return op==KSN_SHIKI_REPEAT||op==KSN_SHIKI_SHIFT||op==KSN_SHIKI_SHIFT_H||
           op==KSN_SHIKI_EACH||op==KSN_SHIKI_FETCH||op==KSN_SHIKI_PUT||
           op==KSN_SHIKI_LOOKUP||op==KSN_SHIKI_LINE_PATTERN;
}
static bool check_inst(const ksn_shiki_inst *i,unsigned inputs){
    if(!stage1(i->op))return false;
    const uint8_t u=used[i->op];
    if((!(u&F_DST)&&i->dst)||(!(u&F_A)&&i->a)||(!(u&F_B)&&i->b)||
       (!(u&F_IMM)&&i->imm)||(!(u&F_AUX)&&i->aux))return false;
    if(i->op==KSN_SHIKI_INPUT){if(i->a>=inputs)return false;}
    else if((u&F_A)&&i->a>=KSN_SHIKI_REGS)return false;
    if((u&F_DST)&&i->dst>=KSN_SHIKI_REGS)return false;
    if((u&F_B)&&i->b>=KSN_SHIKI_REGS)return false;
    switch(i->op){
    case KSN_SHIKI_MUL: return i->aux<=62;
    case KSN_SHIKI_MUL_H: return i->aux<=31;
    case KSN_SHIKI_SHIFT: return i->imm>=-31&&i->imm<=31;
    case KSN_SHIKI_SHIFT_H: return i->imm>=-15&&i->imm<=14;
    case KSN_SHIKI_REPEAT: return i->imm>=1&&i->imm<=255;
    default: return true;
    }
}
/* Loop structure: openers matched with ENDs, at most 8 deep, BREAK_IF_GT
 * inside a loop. loop_end[opener] = its END. */
static bool check_loops(ksn_shiki_plan *p){
    uint8_t stack[KSN_SHIKI_LOOP_DEPTH];
    unsigned depth=0;
    for(unsigned pc=0;pc<p->count;pc++){
        const uint8_t op=p->code[pc].op;
        if(op==KSN_SHIKI_REPEAT||op==KSN_SHIKI_REPEAT_REG){
            if(depth==KSN_SHIKI_LOOP_DEPTH)return false;
            stack[depth++]=(uint8_t)pc;
        }else if(op==KSN_SHIKI_END){
            if(!depth)return false;
            p->loop_end[stack[--depth]]=(uint8_t)pc;
        }else if(op==KSN_SHIKI_BREAK_IF_GT&&!depth)return false;
    }
    return depth==0;
}
static uint16_t le16(const uint8_t *b){return (uint16_t)(b[0]|b[1]<<8);}
static int32_t le32(const uint8_t *b){
    return (int32_t)((uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24);
}

bool ksn_shiki_register(const uint8_t *code,size_t len,const double *args,unsigned nargs,
                        ksn_shiki_plan *plan){
    if(!code||!plan||len<12||memcmp(code,"SKI1",4)||code[4]!=1||code[5]!=0||code[11])return false;
    const unsigned n=code[6],nin=code[7],narg=code[8],ndata=code[9],npatch=code[10];
    if(n<1||n>KSN_SHIKI_CODE||nin>KSN_SHIKI_INPUTS||narg>KSN_SHIKI_ARGS||ndata>4||
       npatch>KSN_SHIKI_PATCHES)return false;
    if(ndata)return false;                       /* stage 1: no data regions */
    if(nargs!=narg||(narg&&!args))return false;
    size_t off=12;
    const uint8_t *in_q=code+off;   off+=nin;
    const uint8_t *arg_q=code+off;  off+=narg;
    off+=4*ndata;
    const uint8_t *patch=code+off;  off+=4*npatch;
    const size_t body=(off+3)&~(size_t)3;
    if(len!=body+12*(size_t)n)return false;      /* exactly the computed size */
    for(size_t k=off;k<body;k++)if(code[k])return false;
    for(unsigned k=0;k<nin;k++)if(in_q[k]>30)return false;
    for(unsigned k=0;k<narg;k++)if(arg_q[k]>30)return false;
    int32_t arg[KSN_SHIKI_ARGS];
    for(unsigned k=0;k<narg;k++)if(!ksn_shiki_from_double(args[k],arg_q[k],&arg[k]))return false;
    plan->count=(uint8_t)n;
    plan->inputs=(uint8_t)nin;
    memcpy(plan->input_q,in_q,nin);
    for(unsigned pc=0;pc<n;pc++){
        const uint8_t *b=code+body+12*pc;
        if(b[10]||b[11])return false;            /* reserved */
        plan->code[pc]=(ksn_shiki_inst){b[0],b[1],b[2],b[3],le32(b+4),le16(b+8)};
    }
    /* Patches: strictly ascending (pc, field), into imm or aux only. */
    int last=-1;
    for(unsigned k=0;k<npatch;k++){
        const uint8_t *q=patch+4*k;
        const unsigned pc=q[0],a=q[1],field=q[2];
        if(q[3]||pc>=n||a>=narg||field>1)return false;
        const int key=(int)(pc*2+field);
        if(key<=last)return false;
        last=key;
        ksn_shiki_inst *i=&plan->code[pc];
        if(field){                               /* aux: an int 0..65535 */
            if(arg_q[a]||arg[a]<0||arg[a]>65535)return false;
            i->aux=(uint16_t)arg[a];
        }else{
            if(int_imm(i->op)&&arg_q[a])return false;
            i->imm=arg[a];
        }
    }
    for(unsigned pc=0;pc<n;pc++)if(!check_inst(&plan->code[pc],nin))return false;
    return check_loops(plan);
}

/* ---- execution (sec.4, sec.4.8) */
static bool coord(int32_t raw,int16_t *px){
    const int64_t p=floor_shift(raw,16);         /* sec.4.5: the pixel */
    if(p<-480||p>720)return false;
    *px=(int16_t)p;
    return true;
}
static ksn_shiki_status emit(ksn_shiki_vm *vm,ksn_proc_segment *out,
                             int16_t x0,int16_t y0,int16_t x1,int16_t y1,uint16_t c){
    if(vm->count==KSN_SHIKI_SEGMENTS)return KSN_SHIKI_LIMIT;
    const int dx=x1>x0?x1-x0:x0-x1,dy=y1>y0?y1-y0:y0-y1;
    const unsigned cost=(unsigned)(dx>dy?dx:dy)+1;
    if(vm->raster+cost>KSN_SHIKI_RASTER)return KSN_SHIKI_LIMIT;
    vm->raster=(uint16_t)(vm->raster+cost);
    out[vm->count++]=(ksn_proc_segment){x0,y0,x1,y1,c};
    return KSN_SHIKI_RUNNING;
}
static int32_t sine(int32_t r){
    const unsigned p=(uint32_t)r&0xFFFFu,quad=p>>14;
    unsigned w=p&0x3FFFu;
    if(quad&1)w=0x4000u-w;
    int64_t v;
    if(w==0x4000u)v=ksn_shiki_sin_table[256];
    else{
        const unsigned i=w>>6,t=w&63u;
        const int64_t d=(int64_t)ksn_shiki_sin_table[i+1]-ksn_shiki_sin_table[i];
        v=ksn_shiki_sin_table[i]+floor_shift(d*(int64_t)t,6);
    }
    return (int32_t)(quad>=2?-v:v);
}

ksn_shiki_status ksn_shiki_draw(const ksn_shiki_plan *plan,const double *inputs,unsigned n,
                                ksn_shiki_vm *vm,ksn_proc_segment out[KSN_SHIKI_SEGMENTS]){
    memset(vm,0,sizeof *vm);
    int32_t in[KSN_SHIKI_INPUTS]={0};
    for(unsigned k=0;k<plan->inputs;k++)
        if(!ksn_shiki_from_double(k<n?inputs[k]:0.0,plan->input_q[k],&in[k]))return KSN_SHIKI_BADINPUT;
    int32_t *r=vm->reg;
    unsigned pc=0;
    for(;;){
        if(vm->steps==KSN_SHIKI_STEPS)return KSN_SHIKI_LIMIT;
        vm->steps++;
        const ksn_shiki_inst *i=&plan->code[pc];
        unsigned next=pc+1;
        switch(i->op){
        case KSN_SHIKI_SET: r[i->dst]=i->imm; break;
        case KSN_SHIKI_INPUT: r[i->dst]=in[i->a]; break;
        case KSN_SHIKI_ADD: r[i->dst]=sat32((int64_t)r[i->a]+r[i->b]); break;
        case KSN_SHIKI_SUB: r[i->dst]=sat32((int64_t)r[i->a]-r[i->b]); break;
        case KSN_SHIKI_NEG: r[i->dst]=sat32(-(int64_t)r[i->a]); break;
        case KSN_SHIKI_MUL: r[i->dst]=sat32(floor_shift((int64_t)r[i->a]*r[i->b],i->aux)); break;
        case KSN_SHIKI_SHIFT:
            r[i->dst]=i->imm>=0?sat32((int64_t)r[i->a]*((int64_t)1<<i->imm))
                               :(int32_t)floor_shift(r[i->a],(unsigned)-i->imm);
            break;
        case KSN_SHIKI_ADD_H: r[i->dst]=sat16((int64_t)sat16(r[i->a])+sat16(r[i->b])); break;
        case KSN_SHIKI_SUB_H: r[i->dst]=sat16((int64_t)sat16(r[i->a])-sat16(r[i->b])); break;
        case KSN_SHIKI_MUL_H:
            r[i->dst]=sat16(floor_shift((int64_t)sat16(r[i->a])*sat16(r[i->b]),i->aux)); break;
        case KSN_SHIKI_SHIFT_H: {
            const int64_t a=sat16(r[i->a]);
            r[i->dst]=i->imm>=0?sat16(a*((int64_t)1<<i->imm)):(int32_t)floor_shift(a,(unsigned)-i->imm);
            break;
        }
        case KSN_SHIKI_SIN: r[i->dst]=sine(r[i->a]); break;
        case KSN_SHIKI_REPEAT: case KSN_SHIKI_REPEAT_REG: {
            int32_t count=i->imm;
            if(i->op==KSN_SHIKI_REPEAT_REG){
                count=r[i->a];
                if(count<0||count>255)return KSN_SHIKI_INVALID;
            }
            if(!count){next=plan->loop_end[pc]+1u;break;}
            vm->loop[vm->depth].pc=(uint8_t)pc;
            vm->loop[vm->depth].remaining=(uint16_t)count;
            vm->depth++;
            break;
        }
        case KSN_SHIKI_END:
            if(--vm->loop[vm->depth-1].remaining)next=vm->loop[vm->depth-1].pc+1u;
            else vm->depth--;
            break;
        case KSN_SHIKI_BREAK_IF_GT:
            if(r[i->a]>r[i->b]){
                next=plan->loop_end[vm->loop[vm->depth-1].pc]+1u;
                vm->depth--;
            }
            break;
        case KSN_SHIKI_MOVE: case KSN_SHIKI_PLOT: case KSN_SHIKI_LINE:
        case KSN_SHIKI_PLOT_C: case KSN_SHIKI_LINE_C: {
            uint16_t c=i->aux;
            if(i->op==KSN_SHIKI_PLOT_C||i->op==KSN_SHIKI_LINE_C){
                if(r[i->dst]<0||r[i->dst]>65535)return KSN_SHIKI_INVALID;
                c=(uint16_t)r[i->dst];
            }
            int16_t x,y;
            if(!coord(r[i->a],&x)||!coord(r[i->b],&y))return KSN_SHIKI_INVALID;
            ksn_shiki_status s=KSN_SHIKI_RUNNING;
            if(i->op==KSN_SHIKI_PLOT||i->op==KSN_SHIKI_PLOT_C)s=emit(vm,out,x,y,x,y,c);
            else if(i->op!=KSN_SHIKI_MOVE&&vm->pen_valid)s=emit(vm,out,vm->pen_x,vm->pen_y,x,y,c);
            if(s!=KSN_SHIKI_RUNNING)return s;
            vm->pen_x=x;vm->pen_y=y;vm->pen_valid=true;
            break;
        }
        default: return KSN_SHIKI_INVALID;   /* registration refuses every other op */
        }
        pc=next;
        if(pc==plan->count)return KSN_SHIKI_DONE;
    }
}
